{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}

import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const root=dirname(fileURLToPath(import.meta.url));
const db=new DatabaseSync(process.env.DB_PATH||join(root,'workboard.sqlite'));
db.exec(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,default_priority TEXT NOT NULL DEFAULT 'Normal');
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title TEXT NOT NULL,completed INTEGER NOT NULL DEFAULT 0,priority TEXT NOT NULL DEFAULT 'Normal',due_date TEXT,position INTEGER NOT NULL DEFAULT 0);`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch {}
try { db.exec("ALTER TABLE projects ADD COLUMN default_priority TEXT NOT NULL DEFAULT 'Normal'"); } catch {}
try { db.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal'"); } catch {}
try { db.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch {}
try { db.exec('ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0'); } catch {}
const server=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');const send=(status,body,type='application/json; charset=utf-8')=>{res.writeHead(status,{'Content-Type':type,'Cache-Control':'no-store'});res.end(body)};const body=async()=>{let raw='';for await(const c of req)raw+=c;try{return JSON.parse(raw)}catch{return null}};
try{
if(url.pathname==='/health'&&req.method==='GET')return send(200,'{"status":"ok"}');
let m=url.pathname.match(/^\/api\/projects\/(\d+)(?:\/(tasks)(?:\/(\d+))?|\/(archive|restore))?$/);
if(m){const id=Number(m[1]), action=m[2] || m[4], project=db.prepare('SELECT * FROM projects WHERE id=?').get(id);if(!project)return send(404,JSON.stringify({error:'Project not found'}));
if(!action&&req.method==='PATCH'){const d=await body();if(['Low','Normal','High'].includes(d?.defaultPriority)){if(project.archived)return send(409,JSON.stringify({error:'Archived project'}));db.prepare('UPDATE projects SET default_priority=? WHERE id=?').run(d.defaultPriority,id);return send(200,JSON.stringify({ok:true}))}if(typeof d?.name==='string'){const name=d.name.trim();if(!name)return send(400,JSON.stringify({error:'Project name is required'}));if(project.archived)return send(409,JSON.stringify({error:'Archived project'}));db.prepare('UPDATE projects SET name=? WHERE id=?').run(name,id);return send(200,JSON.stringify({id,name,archived:false}))}if(!d||!['archive','restore'].includes(d.action))return send(400,'{}');db.prepare('UPDATE projects SET archived=? WHERE id=?').run(d.action==='archive'?1:0,id);return send(200,'{"ok":true}')}
if(action==='tasks'&&req.method==='GET')return send(200,JSON.stringify(db.prepare('SELECT id,project_id AS projectId,title,completed,priority,due_date AS dueDate FROM tasks WHERE project_id=? ORDER BY position,id').all(id)));
if(action==='tasks'&&req.method==='POST'){const d=await body(),title=typeof d?.title==='string'?d.title.trim():'';if(!title)return send(400,JSON.stringify({error:'Task title is required'}));if(project.archived)return send(409,JSON.stringify({error:'Archived project'}));const priority=project.default_priority||'Normal';const position=db.prepare('SELECT COALESCE(MAX(position),-1)+1 AS n FROM tasks WHERE project_id=?').get(id).n;const r=db.prepare('INSERT INTO tasks(project_id,title,priority,position) VALUES(?,?,?,?)').run(id,title,priority,position);return send(201,JSON.stringify({id:Number(r.lastInsertRowid),projectId:id,title,completed:0,priority}))}
if(action==='tasks'&&m[3]&&req.method==='PATCH'){const d=await body();if(project.archived)return send(409,'{}');const taskId=Number(m[3]);if(Object.hasOwn(d||{},'moveTo')){const destination=Number(d.moveTo),target=db.prepare('SELECT * FROM projects WHERE id=?').get(destination);if(!target||target.archived||destination===id)return send(400,'{}');const task=db.prepare('SELECT id FROM tasks WHERE id=? AND project_id=?').get(taskId,id);if(!task)return send(404,'{}');const position=db.prepare('SELECT COALESCE(MAX(position),-1)+1 AS n FROM tasks WHERE project_id=?').get(destination).n;db.prepare('UPDATE tasks SET project_id=?,position=? WHERE id=?').run(destination,position,taskId);return send(200,'{"ok":true}') }if(Object.hasOwn(d||{},'dueDate')){const raw=typeof d.dueDate==='string'?d.dueDate.trim():null;if(raw!==''&&(!raw||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(raw)||!validDate(raw)))return send(400,JSON.stringify({error:'Due date must be a valid YYYY-MM-DD date'}));const r=db.prepare('UPDATE tasks SET due_date=? WHERE id=? AND project_id=?').run(raw||null,taskId,id);return send(r.changes?200:404,'{}')}if(['Low','Normal','High'].includes(d?.priority)){const r=db.prepare('UPDATE tasks SET priority=? WHERE id=? AND project_id=?').run(d.priority,taskId,id);return send(r.changes?200:404,'{}')}if(typeof d?.title==='string'){const title=d.title.trim();if(!title)return send(400,JSON.stringify({error:'Task title is required'}));const r=db.prepare('UPDATE tasks SET title=? WHERE id=? AND project_id=?').run(title,taskId,id);return send(r.changes?200:404,JSON.stringify({id:taskId,projectId:id,title}))}if(typeof d?.completed!=='boolean')return send(400,'{}');const r=db.prepare('UPDATE tasks SET completed=? WHERE id=? AND project_id=?').run(+d.completed,taskId,id);return send(r.changes?200:404,'{}')}
}
if(url.pathname==='/api/projects'&&req.method==='GET')return send(200,JSON.stringify(db.prepare(`SELECT p.id,p.name,p.archived,p.default_priority AS defaultPriority,COUNT(t.id) totalCount,COALESCE(SUM(t.completed),0) completedCount FROM projects p LEFT JOIN tasks t ON t.project_id=p.id GROUP BY p.id ORDER BY p.id`).all().map(p=>({...p,archived:!!p.archived}))));
if(url.pathname==='/api/projects'&&req.method==='POST'){const d=await body(),name=typeof d?.name==='string'?d.name.trim():'';if(!name)return send(400,JSON.stringify({error:'Project name is required'}));const r=db.prepare('INSERT INTO projects(name) VALUES(?)').run(name);return send(201,JSON.stringify({id:Number(r.lastInsertRowid),name,archived:false,defaultPriority:'Normal',totalCount:0,completedCount:0}))}
if(req.method==='GET'&&(url.pathname==='/'||url.pathname.startsWith('/projects/')))return send(200,await readFile(join(root,'public/index.html'),'utf8'),'text/html; charset=utf-8');
send(404,JSON.stringify({error:'Not found'}));}catch(e){console.error(e);send(500,JSON.stringify({error:'Internal server error'}))}});
function validDate(value){const [y,m,d]=value.split('-').map(Number);if(y<1||m<1||m>12)return false;const leap=y%4===0&&(y%100!==0||y%400===0),days=[31,leap?29:28,31,30,31,30,31,31,30,31,30,31];return d>=1&&d<=days[m-1]}
server.listen(Number(process.env.PORT||8080),'0.0.0.0');

